# TYPE 162  CoolingTower   (SetNumberofParameters(13), Inputs(7+maxcel), Outputs(11+maxcel))
# Instances: model.cooling_tower  (UNIT 40)
# Note: maxcel = param[4] (number of operating cells, 1..8); inputs and outputs are variable-length.
# --------------------------------------------------------------
# PARAMS
#   [1] mode              (1=use NTU coefficients directly, 2=curve-fit from performance data file)
#   [2] control_mode      (0=relative fan speeds provided as inputs, 1=temperature-seek control)
#   [3] flow_geometry     (1=counterflow, 2=crossflow)
#   [4] max_cells         (number of cells in the cooling tower, 1..8)
#   [5] fan_max           (maximum volumetric airflow per cell, m3/h)
#   [6] pwr_max           (maximum fan power per cell at maximum airflow, kJ/h)
#   [7] fan_off           (minimum/natural convection airflow per cell, m3/h)
#   [8] v_sump            (sump volume, m3; use 0 for no sump)
#   [9] ua_sump           (sump overall thermal loss coefficient to ambient, kJ/h.K)
#   [10] t_start          (initial sump temperature, C)
#   [11] c1               (mass transfer constant in NTU correlation; set by mode-2 curve fit)
#   [12] c2_minus1        (mass transfer exponent minus 1 in NTU correlation; set by mode-2 curve fit)
#   [13] i_ptr            (print flag for mode-2 curve-fit results: 0=no print, 1=print to listing file)
# INPUTS
#   [1] T_water_in        (inlet water temperature, C)
#   [2] m_dot_water_in    (inlet water mass flow rate, kg/h)
#   [3] T_db              (ambient dry-bulb temperature, C)
#   [4] T_wb              (ambient wet-bulb temperature, C)
#   [5] T_want            (desired outlet water temperature for temperature-seek control, C)
#   [6] T_main            (makeup water temperature, C)
#   [7] q_sump            (auxiliary energy addition to sump, kJ/h)
#   [8..7+maxcel] frac_i  (relative fan speed for cell i, 0..1; used when control_mode=0)
# OUTPUTS
#   [1] T_sump            (sump/mixed outlet water temperature, C)
#   [2] m_dot_water_out   (outlet water mass flow rate, kg/h)
#   [3] fan_power         (total fan power consumption, kJ/h)
#   [4] q_rejection       (total tower heat rejection, kJ/h)
#   [5] T_water_out       (tower water outlet temperature before sump mixing, C)
#   [6] m_dot_loss        (evaporative water loss rate, kg/h)
#   [7] T_air_out_db      (mixed outlet air dry-bulb temperature, C)
#   [8] T_air_out_wb      (mixed outlet air wet-bulb temperature, C)
#   [9] w_air_out         (mixed outlet air humidity ratio, kg_w/kg_da)
#   [10] m_dot_air        (total air mass flow rate through tower, kg/h)
#   [11] delta_u          (change in sump internal energy since start of simulation, kJ)
#   [12..11+maxcel] frac_cell_i  (actual relative fan speed for cell i)
